ValidationRule.errorConditionFormula:
AND(
    /* Only on edit (not on create) */
    NOT(ISNEW()),

    /* Target the specific profile */
    $Profile.Id = "00eRT000001cxZZ",

    /* Block if either field is being changed */
    OR(
        ISCHANGED(Status),
        ISCHANGED(RecordTypeId)
    )
)
